<?php
declare(strict_types=1);
namespace Safaricom\Mpesa\Support;
final class Env { private static array $loaded=[]; public static function load(string $path): void { if(isset(self::$loaded[$path])||!is_file($path)||!is_readable($path)) return; $lines=file($path,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[]; foreach($lines as $line){$line=trim($line); if($line===''||str_starts_with($line,'#')||!str_contains($line,'=')) continue; [$key,$value]=explode('=',$line,2); $key=trim($key);$value=trim($value); if($key==='') continue; if((str_starts_with($value,'"')&&str_ends_with($value,'"'))||(str_starts_with($value,"'")&&str_ends_with($value,"'")))$value=substr($value,1,-1); if(getenv($key)===false){putenv($key.'='.$value);$_ENV[$key]=$value;}} self::$loaded[$path]=true;} public static function get(string $key,?string $default=null):?string{$value=getenv($key);if($value!==false)return $value;if(array_key_exists($key,$_ENV))return(string)$_ENV[$key];if(array_key_exists($key,$_SERVER))return(string)$_SERVER[$key];return $default;} }
